svg.script:
document.querySelectorAll('.room-hit').forEach(el => {
  el.addEventListener('click', () => {
    document.querySelectorAll('.room-hit').forEach(x => x.classList.remove('selected'));
    el.classList.add('selected');
    const detail = {
      id: el.dataset.roomId,
      number: el.dataset.roomNumber,
      area_m2: Number(el.dataset.areaM2),
      status: el.dataset.status
    };
    window.dispatchEvent(new CustomEvent('room-select', { detail }));
    console.log('room-select', detail);
  });
});
